import { Box } from "@mui/material";
import { BackgroundMobile } from "./components/backgroundMobile";
import learningTogether from "./media/projectsData/learningTogether.png";
import technoStore from "./media/projectsData/technoStore.jpg";
import chatBot from "./media/projectsData/chatBot.png";
import { CardMobile } from "./components/card";
import { useEffect, useRef, useState } from "react";
import gsap from "gsap";
import { useWindowSize } from "../../helpers/windowSize";
import { TitleMobile } from "./components/titleMobile";

export const MobileHomepage = () => {
  const { width } = useWindowSize();
  const boxRef = useRef(null);
  const [scrollValue, setScrollValue] = useState(0);
  const touchStartRef = useRef(0);
  const [boxWidth, setBoxWidth] = useState(0)

  useEffect(() => {
    setBoxWidth(0.8*width)
  }, [width])

  useEffect(() => {
    gsap.to(boxRef.current, {
      left: width - scrollValue,
      ease: "power2.out",
      duration: 0.8, // Увеличил длительность анимации
    });

    gsap.to(".text", {
      x: scrollValue < 100 ? -scrollValue : 0,
      opacity: scrollValue < 100 ? 1 : 0, // Fade out text if scrollValue >= 100
      ease: "power2.out",
      duration: 0.8,
    });
  }, [scrollValue, width]);

  const handleTouchStart = (e) => {
    touchStartRef.current = e.touches[0].clientY;
  };

  const handleTouchMove = (e) => {
    const touchEnd = e.touches[0].clientY;
    const delta = touchStartRef.current - touchEnd;

    if (Math.abs(delta) > 5) {
      setScrollValue((prev) =>
        Math.min(Math.max(prev + delta * 0.1, 1), (width + 50) * (data.length)) // Уменьшил скорость
      );
    }
  };

  const data = [
    {
      title: "LearningTogether",
      img: learningTogether,
      link: "https://spoluseucime.cz/",
    },
    {
      title: "TechnoStore",
      img: technoStore,
      link: "https://github.com/olegurcenko/technostore",
    },
    {
      title: "ChatBot",
      img: chatBot,
      link: "https://github.com/olegurcenko/chatbot",
    },
  ];

  return (
    <Box onTouchStart={handleTouchStart} onTouchMove={handleTouchMove}>
      <BackgroundMobile>
        <Box
          sx={{
            width: "100vw",
            height: "100vh",
            overflow: "hidden",
            position: "relative",
            touchAction: "none",
          }}
        >
          <Box
            ref={boxRef}
            onTouchStart={handleTouchStart}
            onTouchMove={handleTouchMove}
            sx={{
              left: "100%",
              position: "absolute",
              display: "flex",
              padding: "20px",
            }}
          >
            {/* 92/150 */}
            {data.map((_, index) => (
              <CardMobile
                key={index}
                index={index}
                link={_.link}
                img={_.img}
                title={_.title}
              />
            ))}
          </Box>
          <TitleMobile/>
        </Box>
      </BackgroundMobile>
    </Box>
  );
};
