import { Box, Typography } from "@mui/material";
import { useEffect, useRef, useState } from "react";
import gsap from "gsap";
import whiteNoise from "../media/noise.gif";
import { useWindowSize } from "../../../helpers/windowSize";

export const CardMobile = ({ index, img, link, onWheel, cursorMover, onMouseLeave, title }) => {
  const badgeRef = useRef(null);
  const whiteNoiseRef = useRef(null);
  const {width, height} = useWindowSize()
  const [cardHeight, setCardHeight] = useState(0)
  const [cardWidth, setCardWidth] = useState(0)
  useEffect(() => {

    if (width > height) {
      setCardWidth(0.8*width)
      setCardHeight(0.45*height)
    } else {
      setCardHeight(0.8*height)
      setCardWidth(0.45*height)
    }
  })

  return (
    <Box
      sx={{
        position: "relative",
        zIndex: 11,
        top: "5vh",
        margin: "20px auto",
        border: "1px solid rgb(43 222 209)",
        width: cardWidth,
        height: cardHeight,
        overflow: "hidden",
        padding: '10px',
        marginRight: '30px',
      }}
    >
      <Box
        sx={{
          backgroundImage: `url(${img})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
          width: "100%",
          height: "100%",
          position: "relative",
        }}
      >
        <Box
          ref={whiteNoiseRef}
          sx={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            opacity: 0.05,
            backgroundImage: `url(${whiteNoise})`,
          }}
        />

        {/* Badge */}
        <Box
          ref={badgeRef}
          sx={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            opacity: 1,
            transition: "opacity 0.5s ease-in-out",
          }}
        >
          <Typography
            sx={{
              padding: "15px 30px",
              backgroundColor: "rgba(167, 241, 236, 0.4)",
              border: "1px solid rgb(43 222 209)",
              fontSize: "20px",
              color: "rgb(43 222 209)",
              borderRadius: "10px",
              textAlign: "center",
            }}
          >
            {title}
          </Typography>
        </Box>
        <a
          href={link}
          target="_blank"
          rel="noopener noreferrer"
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            top: 0,
            left: 0,
            zIndex: 10,
          }}
        ><span/></a>
      </Box>
    </Box>
  );
};
