import { Box, Typography } from "@mui/material";
import { Link } from "react-router-dom";
import whiteNoise from '../media/noise.gif';
import { useRef } from "react";
import gsap from "gsap";

export const Card = ({ index, img, link, onWheel, cursorMover, onMouseLeave, title }) => {

  const badgeRef = useRef(null);
  const whiteNoiseRef = useRef(null)

  const badgeDisplayer = (e) => {
    gsap.to(badgeRef.current, {
      opacity: 1,
      duration: .5
    })
    gsap.to(whiteNoiseRef.current, {
      opacity: 0,
      duration: .7
    })
  }

  const badgeHider = (e) => {
    gsap.to(badgeRef.current, {
      opacity: 0,
      duration: .5
    })
    gsap.to(whiteNoiseRef.current, {
      opacity: .05,
      duration: .7
    })
  }

  const handleClick = () => {
    window.open(link, "_blank", "noopener,noreferrer");
  };
  return (
    <Link
      onMouseMove={cursorMover}
      onMouseLeave={onMouseLeave}
      onWheel={onWheel}
      to={link}
      key={index}
      className={index % 2 === 0 ? "firstTypeCard" : "secTypeCard"}
      style={{
        top: "10vh",
        marginRight: "40px",
        position: "relative",
        padding: "5px 10px",
        zIndex: 13,
        border: "1px black solid",
        display: "block",
      }}
    >
      <Box
        sx={{
          backgroundImage: `url(${img})`,
          backgroundSize: "cover",
          position: "relative",
        }}
      >
        <Link
          onClick={handleClick}
          onMouseMove={badgeDisplayer}
          onMouseOut={badgeHider}
          style={{
            position: "absolute",
            top: "10px",
            left: "10px",
            color: "white",
            padding: "5px 10px",
            borderRadius: "5px",
            textDecoration: "none",
            fontWeight: "bold",
            height: "630px",
            width: "1290px",
            zIndex: 10, // Ensures the link is above everything
          }}
        >
        </Link>
          <Box 
          ref={badgeRef}
          sx={{
            top: "10px",
            left: "10px",
            height: "630px",
            width: "1290px",
            opacity: "0",
            position: "absolute",
            zIndex: 9,
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center'
          }}>
            <Typography sx={{
              padding: '50px 100px',
              backgroundColor: 'rgba(167, 241, 236, 0.4)',
              width: 'fit-content',
              border: "1px solid rgb(43 222 209)",
              fontSize: '36px',
              color: 'rgb(43 222 209)'
            }}>{title}</Typography>
          </Box>
        <Box
        ref={whiteNoiseRef}
          style={{
            height: "630px",
            width: "1290px",
            opacity: ".05",
            backgroundImage: `url(${whiteNoise})`,
          }}
        ></Box>
      </Box>
    </Link>
  );
};
