import { Box } from "@mui/material";
import FiberManualRecordRoundedIcon from "@mui/icons-material/FiberManualRecordRounded";
import whiteNoise from "../media/noise.gif";
import { useRef, useState } from "react";
import { useWindowSize } from "../../../helpers/windowSize";
import gsap from "gsap";

export const Background = ({children}) => {
	const [position, setPosition] = useState({ x: 0, y: 0 });
  const { width, height } = useWindowSize();
  const circleRefs = useRef([]);

  circleRefs.current.forEach((element, index) => {
	gsap.to(element, {
		y: `+=${index % 2 === 0 ? 15 : -15}`,
		x: `+=${index % 2 === 0 ? -15 : 15}`,
		duration: `2`,
		ease: "sine.inOut",
		yoyo: true,
		repeat: -1
	  });
	});

  const handleMouseMove = (event) => {
    const { clientX, clientY } = event;
    setPosition({ x: clientX, y: clientY });

    let xTemp = (clientX - width / 2) / (width / 2) * 10;
    let yTemp = (clientY - height / 2) / (height / 2) * 10;


    circleRefs.current.forEach((element) => {
      if (element) {
        gsap.to(element, {
          transform: `perspective(200px) rotateY(${xTemp}deg) rotateX(${yTemp}deg)`,
          duration: 0.4,
          ease: "power2.out",
        });
      }
    });
    gsap.to('.firstTypeCard', {
      transform: `perspective(200px) rotateY(${xTemp / 10}deg) rotateX(${yTemp / 10}deg)`,
          duration: 0.4,
          ease: "power2.out",
    })
    gsap.to('.secTypeCard', {
      transform: `perspective(200px) rotateY(${-xTemp / 10}deg) rotateX(${yTemp / 10}deg)`,
          duration: 0.4,
          ease: "power2.out",
    })
  };

  return (
    <Box onMouseMove={handleMouseMove} sx={{ height: "100vh", overflow: "hidden", backgroundColor: "#154d49", opacity: .9, overflowBlock: 'hidden'}}>
      {[
        { top: "20%", left: "40%" },
        { top: "25%", left: "10%" },
        { top: "-5%", left: "32%" },
        { top: "70%", left: "25%" },
        { top: "40%", left: "23%" },
        { top: "3%", left: "0%" },
      ].map((pos, i) => (
        <FiberManualRecordRoundedIcon
          key={i}
          ref={(el) => (circleRefs.current[i] = el)}
          sx={{
            fontSize: "490px",
            position: "absolute",
            opacity: 0.4,
            color: "#009b77",
            zIndex: 1,
            top: pos.top,
            left: pos.left,
          }}
        />
      ))}
      <Box
        sx={{
          backgroundImage: `url(${whiteNoise})`,
          position: "absolute",
          left: 0,
          top: 0,
          height: "100vh",
          width: "100vw",
          opacity: 0.05,
          backdropFilter: "blur(20px)",
          zIndex: 3,
        }}
      />
	  {children}
    <Box sx={{
			position: "absolute",
			top: 0,
			left: 0,
			width: "100vw",
			height: "100vh",
			backdropFilter: "blur(10px)",
			zIndex: 2,
		  }}></Box>
    </Box>
  );
}