import { Box } from "@mui/material";
import FiberManualRecordRoundedIcon from "@mui/icons-material/FiberManualRecordRounded";
import whiteNoise from "../media/noise.gif";
import { useEffect, useRef } from "react";
import gsap from "gsap";

export const BackgroundMobile = ({ children }) => {
  const circleRefs = useRef([]);

  useEffect(() => {
    circleRefs.current.forEach((element, index) => {
      if (element) {
        gsap.to(element, {
          y: index % 2 === 0 ? 10 : -10,
          x: index % 2 === 0 ? -10 : 10,
          duration: 5,
          ease: "sine.inOut",
          yoyo: true,
          repeat: -1,
        });
      }
    });
  }, []);

  return (
    <Box
      sx={{
        height: "100vh",
        overflow: "hidden",
        backgroundColor: "#154d49",
        opacity: 0.9,
        position: "relative",
        touchAction: "none",
      }}
    >
      {[
        { top: "10%", left: "20%" },
        { top: "30%", left: "60%" },
        { top: "50%", left: "10%" },
        { top: "70%", left: "80%" },
        { top: "90%", left: "40%" },
        { top: "20%", left: "75%" },
      ].map((pos, i) => (
        <FiberManualRecordRoundedIcon
          key={i}
          ref={(el) => (circleRefs.current[i] = el)}
          sx={{
            fontSize: "200px", // Уменьшен размер для избежания выхода за границы
            position: "absolute",
            opacity: 0.3,
            color: "#009b77",
            zIndex: 1,
            top: pos.top,
            left: pos.left,
            transform: "translate(-50%, -50%)",
          }}
        />
      ))}

      {/* Наложение шума */}
      <Box
        sx={{
          backgroundImage: `url(${whiteNoise})`,
          position: "absolute",
          left: 0,
          top: 0,
          height: "100vh",
          width: "100vw",
          opacity: 0.05,
          backdropFilter: "blur(20px)",
          zIndex: 3,
        }}
      />

      {children}

      {/* Блюр-слой */}
      <Box
        sx={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          backdropFilter: "blur(10px)",
          zIndex: 2,
        }}
      />
    </Box>
  );
};
