import { Box, Typography } from "@mui/material";
import { Background } from "../homepage/components/background";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import gsap from "gsap";
import { useEffect, useRef, useState } from "react";
import { useWindowSize } from "../../helpers/windowSize";
import whiteNoise from "./media/noise.gif";
import { Card } from "./components/card";
import { ButtonAnimated } from "./components/button";
import badge from "./media/badge.svg";
import learningTogether from "./media/projectsData/learningTogether.png";
import technoStore from "./media/projectsData/technoStore.jpg";
import chatBot from "./media/projectsData/chatBot.png";
import { BadgeSpin } from "./components/badge";
import { Title } from "./components/title";
import { ReactComponent as TgIcon } from "./media/telegram.svg";
import { ReactComponent as GhIcon } from "./media/github.svg";
import { ReactComponent as IgIcon } from "./media/instagram.svg";

gsap.registerPlugin(ScrollTrigger);

export const Homepage = () => {
  const { width } = useWindowSize();
  const boxRef = useRef(null);
  const linksRef = useRef(null);
  const linksInsideRef = useRef(null);
  const cursorRef = useRef(null);
  const [scrollValue, setScrollValue] = useState(0);

  useEffect(() => {
    gsap.to(".text img", {
      rotate: 360,
      duration: 10,
      ease: "linear",
    });
  }, []);
  const handleCursorMover = (e) => {
    gsap.to(cursorRef.current, {
      opacity: 0.6,
      x: e.clientX - 35,
      y: e.clientY - 5,
      duration: 0.2,
    });
  };

  const cursorDisappear = (e) => {
    gsap.to(cursorRef.current, {
      opacity: 0,
      duration: 0.2,
    });
  };
  useEffect(() => {
    gsap.to(".text", {
      opacity: 0,
      scrollTrigger: {
        trigger: ".text",
        start: "top 100px",
        toggleActions: "play none none reverse",
      },
    });
  }, []);

  useEffect(() => {
    gsap.to(boxRef.current, {
      left: width * 0.6 - scrollValue,
      ease: "power2.out",
    });

    gsap.to(".text", {
      x: scrollValue < 100 ? -scrollValue : 0,
      opacity: scrollValue < 100 ? 1 : 0, // Fade out text if scrollValue >= 100
      ease: "power2.out",
      duration: 0.5,
    });
  }, [scrollValue, width]);

  const openLinks = () => {
    const tl = gsap.timeline();
    tl.to(linksRef.current, {
      width: "100vw",
    });
    tl.to(linksRef.current, {
      opacity: 1,
      duration: 1,
    });
  };

  const closeLinks = () => {
    const tl = gsap.timeline();
    tl.to(linksRef.current, {
      opacity: 0,
      duration: 1,
    });
    tl.to(linksRef.current, {
      width: "0",
    });
  };

  const data =
    [
      {
        title: "LearningTogether",
        img: learningTogether,
        link: "https://spoluseucime.cz/",
      },
      {
        title: "TechnoStore",
        img: technoStore,
        link: "https://github.com/olegurcenko/technostore",
      },
      {
        title: "ChatBot",
        img: chatBot,
        link: "https://github.com/olegurcenko/chatbot",
      },
    ] || [];

  gsap.fromTo(
    ".firstTypeCard",
    {
      top: "10vh",
    },
    {
      duration: `2`,
      top: "12vh",
      ease: "sine.inOut",
      yoyo: true,
      repeat: -1,
    }
  );

  gsap.fromTo(
    ".secTypeCard",
    {
      top: "10vh",
    },
    {
      duration: `2`,
      top: "12vh",
      ease: "sine.inOut",
      yoyo: true,
      repeat: -1,
    }
  );

  const handleScroll = (e) => {
    setScrollValue((prev) =>
      Math.min(Math.max(prev + e.deltaY, 0), 1350 * data.length - 500)
    ); // Limit movement
  };

  return (
    <Background>
      <Box
        ref={boxRef}
        sx={{
          left: "60%",
          position: "absolute",
          display: "flex", // Выстраивает карточки в линию
          padding: "20px",
        }}
      >
        {data.map((_, index) => (
          <Card
            key={index}
            index={index}
            link={_.link}
            img={_.img}
            title={_.title}
            onWheel={handleScroll}
            cursorMover={handleCursorMover}
            onMouseLeave={cursorDisappear}
          />
        ))}
      </Box>
      <Box
        sx={{
          backgroundImage: `url(${whiteNoise})`,
          position: "absolute",
          left: 0,
          top: 0,
          height: "100vh",
          width: "100vw",
          opacity: 0.02,
          backdropFilter: "blur(20px)",
          zIndex: 5,
          pointerEvents: "none",
        }}
      ></Box>
      <Box
        sx={{
          position: "absolute",
          zIndex: 4,
          width: "100vw",
          height: "100vh",
          background:
            "linear-gradient(to bottom,rgb(0, 0, 0),rgba(255, 255, 255, 0), rgba(255, 255, 255, 0))", // gradient from pink to orange
          display: "flex",
          alignItems: "start",
          justifyContent: "space-between",
          opacity: "1",
        }}
      >
        <Typography
          sx={{
            color: "rgb(43 222 209)",
            marginTop: "20px",
            marginLeft: "20px",
            zIndex: "6",
            position: "relative",
            fontSize: "24px",
            opacity: ".6",
            fontFamily: "Noto Sans",
            fontWeight: 900,
            letterSpacing: -1,
          }}
        >
          YurWell
        </Typography>
        <ButtonAnimated btnText={"links"} btnFunc={openLinks} />
      </Box>
      <Title handleFunc={handleScroll} />
      <BadgeSpin />
      <Box
        ref={cursorRef}
        sx={{
          position: "fixed",
          width: "70px",
          height: "30px",
          opacity: 0,
          zIndex: 1000,
          pointerEvents: "none",
          border: "1px solid rgb(43 222 209)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: "rgb(43 222 209)",
        }}
      >
        Click me
      </Box>
      <Box
        ref={linksRef}
        onClick={closeLinks}
        sx={{
          position: "absolute",
          left: 0,
          top: 0,
          backdropFilter: "blur(20px)",
          zIndex: 14,
          width: "0vw",
          height: "100vh",
          opacity: 0,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          
        }}
      >
        <Box
        ref={{linksInsideRef}}
          sx={{
            display: "flex",
            alignItems: "center",
            height: "50%",
            width: '60%',
            justifyContent: "center",
            borderRadius: '24px',
            zIndex: 14,
            position: 'absolute',
            backgroundColor: 'rgba(0, 0, 0, .6)'
          }}
        >
          <a href="https://your-link.com">
          <TgIcon style={{ fill: "rgb(43, 222, 209)", height: "100px", marginInline: "40px" }} />
          </a>
          <a href="https://your-link.com">
          <IgIcon style={{ fill: "rgb(43, 222, 209)", height: "100px", marginInline: "40px" }} />
          </a>
          <a href="https://your-link.com">
          <GhIcon style={{ fill: "rgb(43, 222, 209)", height: "100px", marginInline: "40px" }} />
          </a>
        </Box>
      </Box>
    </Background>
  );
};
