import { Button, Typography } from "@mui/material";
import gsap from "gsap";
import { useRef, useEffect } from "react";

export const ButtonAnimated = ({ btnText, btnFunc }) => {
  const buttonRef = useRef(null);

  useEffect(() => {
    const btn = buttonRef.current;
    if (!btn) return;

    const handleMouseMove = (e) => {
      const { left, top, width, height } = btn.getBoundingClientRect();
      const xOffset = gsap.utils.clamp(-20, 20, e.clientX - left - width / 2);
      const yOffset = gsap.utils.clamp(-10, 10, e.clientY - top - height / 2);

      gsap.to(btn, {
        x: xOffset,
        y: yOffset,
        scale: 1.05, // Slight enlargement for a hover effect
        duration: 0.3,
        ease: "power2.out",
      });
    };

    const handleMouseOut = () => {
      gsap.to(btn, {
        x: 0,
        y: 0,
        scale: 1,
        duration: 0.6, // Smooth return
        ease: "elastic.out(1, 0.4)", // Adds a nice bounce-back effect
      });
    };

    btn.addEventListener("mousemove", handleMouseMove);
    btn.addEventListener("mouseleave", handleMouseOut);

    return () => {
      btn.removeEventListener("mousemove", handleMouseMove);
      btn.removeEventListener("mouseleave", handleMouseOut);
    };
  }, []);

  return (
    <Button
      ref={buttonRef}
      onClick={btnFunc}
      sx={{
        marginTop: "20px",
        marginRight: "40px",
        border: "1px solid rgb(43 222 209)",
        height: "20px",
        borderRadius: 0,
        opacity: 0.6,
        position: "relative",
        overflow: "hidden",
        transition: "opacity 0.3s ease",
        "&:hover": { opacity: .8 },
      }}
    >
      <Typography
        sx={{
          fontSize: "14px",
          color: "rgb(43 222 209)",
          fontWeight: "bold",
          fontFamily: "Noto Sans",
          textTransform: "uppercase",
        }}
      >
        {btnText}
      </Typography>
    </Button>
  );
};
